const items = $input.all();
const results = [];

for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const buffer = await this.helpers.getBinaryDataBuffer(i, 'data');
  const base64 = buffer.toString('base64');

  results.push({
    json: {
      base64: base64,
      mimeType: item.binary.data.mimeType,
      fileName: item.binary.data.fileName
    },
    binary: item.binary
  });
}

return results;

const items = $input.all();
const results = [];

for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const part = item.json.candidates[0].content.parts.find(p => p.inlineData);

  if (!part) {
    continue; // skip if no image came back
  }

  const base64 = part.inlineData.data;
  const mimeType = part.inlineData.mimeType || 'image/png';
  const buffer = Buffer.from(base64, 'base64');
  const fileName = `studio_render_${i}.png`;

  results.push({
    json: {
      fileName: fileName,
      fileSize: buffer.length,
      mimeType: mimeType
    },
    binary: {
      data: await this.helpers.prepareBinaryData(buffer, fileName, mimeType)
    }
  });
}

return results;

