// Org-scoped VNTANA API token (X-AUTH-TOKEN). Get one via the VNTANA login + refresh-token flow.
const REFRESH_TOKEN = 'YOUR_VNTANA_API_TOKEN';
const CLIENT_UUID = 'YOUR_WORKSPACE_UUID';
const PRODUCT_UUID = $('Webhook').first().json.body.product.uuid;

const headers = {
  'x-auth-token': `Bearer ${REFRESH_TOKEN}`,
  'Content-Type': 'application/json'
};

const tagText = $('Gemini Tagging').first().json.candidates[0].content.parts[0].text;
const tagNames = JSON.parse(tagText).tags;

const tagUuids = [];
for (const name of tagNames) {
  let uuid = null;

  try {
    const resp = await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://api-platform.vntana.com/v1/tags/create',
      headers,
      body: { clientUuid: CLIENT_UUID, name },
      json: true
    });
    if (resp && resp.success && resp.response && resp.response.uuid) {
      uuid = resp.response.uuid;
    }
  } catch (e) {
    // 409 = already exists, fall through to search
  }

  if (!uuid) {
    try {
      const resp = await this.helpers.httpRequest({
        method: 'POST',
        url: 'https://api-platform.vntana.com/v1/tags/search',
        headers,
        body: { clientUuid: CLIENT_UUID, page: 1, searchTerm: name, size: 10 },
        json: true
      });
      const grid = (resp && resp.response && resp.response.grid) || [];
      const exact = grid.find(t => t.name === name);
      if (exact) uuid = exact.uuid;
    } catch (e) {}
  }

  if (uuid) tagUuids.push(uuid);
}

// Get current asset for the PUT body
const assetResp = await this.helpers.httpRequest({
  method: 'GET',
  url: `https://api-platform.vntana.com/v1/products/${PRODUCT_UUID}`,
  headers,
  json: true
});
const asset = assetResp.response;

const existingUuids = (asset.tags || []).map(t => t.uuid);
// Cap at 10 total tags, prioritizing newly generated AI tags
const merged = [...new Set([...tagUuids, ...existingUuids])];
const allTagUuids = merged.slice(0, 10);

const updateBody = {
  uuid: PRODUCT_UUID,
  clientUuid: asset.clientUuid,
  name: asset.name,
  description: asset.description || '',
  tagsUuids: allTagUuids,
  locationsUuids: [],
  attributes: asset.attributes || {},
  pipelineUuid: asset.pipelineUuid,
  presetUuid: asset.presetUuid || '',
  assetType: asset.assetType || 'THREE_D',
  modelOpsParameters: asset.modelOpsParameters || {},
  publishToStatus: asset.status || 'LIVE_PUBLIC',
  projectsUuids: [],
  project: null,
  deleteAsset: false
};

const updateResp = await this.helpers.httpRequest({
  method: 'PUT',
  url: 'https://api-platform.vntana.com/v1/products',
  headers,
  body: updateBody,
  json: true
});

return [{
  json: {
    tagsAdded: tagNames,
    tagsResolvedUuids: tagUuids,
    finalTagsOnAsset: allTagUuids,
    updateSuccess: updateResp && updateResp.success,
    updateResponse: updateResp
  }
}];

return $input.all().filter(item => {
  const name = (item.binary && item.binary.data && item.binary.data.fileName) || '';
  return !name.startsWith('studio_render_');
});
